#[inline]
fn checked_add_usize(left: usize, right: usize, context: &str) -> usize {
    match left.checked_add(right) {
        Some(sum) => sum,
        None => roc_unreachable(context),
    }
}

#[inline]
fn checked_mul_usize(left: usize, right: usize, context: &str) -> usize {
    match left.checked_mul(right) {
        Some(product) => product,
        None => roc_unreachable(context),
    }
}

#[inline]
fn shifted_capacity(capacity: usize) -> usize {
    // The shifted form keeps one bit for the seamless-slice tag.
    if capacity > isize::MAX as usize {
        roc_unreachable("Roc capacity does not fit its shifted representation")
    }
    capacity << 1
}

/// Uniform ABI function pointer stored in `RocErasedCallablePayload`.
///
/// The final `reuse` pointer is nullable. Non-null must be the callable data
/// pointer whose inline capture begins at `capture`; it transfers one owned
/// reference to the callee. The caller must not use or decref that ownership
/// unit after the call. The callee consumes it exactly once, whether or not the
/// result can reuse the allocation.
pub type RocErasedCallableFn = extern "C" fn(*mut raw::RocSymbolAdapter, *mut u8, *const u8, *mut u8, *mut u8, *mut *const c_void);

/// Final-drop callback for inline erased-callable captures.
pub type RocErasedCallableOnDrop = extern "C" fn(*mut u8, *mut raw::RocSymbolAdapter);

/// Payload header for `Box(function)`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct RocErasedCallablePayload {
    pub callable_fn_ptr: RocErasedCallableFn,
    pub on_drop: Option<RocErasedCallableOnDrop>,
    pub on_copy: Option<extern "C" fn(*mut u8, isize)>,
    pub capture_size: usize,
}

const _: () = assert!(core::mem::size_of::<RocErasedCallablePayload>() == 4 * core::mem::size_of::<usize>(), "RocErasedCallablePayload size mismatch");
const _: () = assert!(core::mem::offset_of!(RocErasedCallablePayload, callable_fn_ptr) == 0, "RocErasedCallablePayload.callable_fn_ptr offset mismatch");
const _: () = assert!(core::mem::offset_of!(RocErasedCallablePayload, on_drop) == core::mem::size_of::<usize>(), "RocErasedCallablePayload.on_drop offset mismatch");

pub const ROC_ERASED_CALLABLE_CAPTURE_ALIGNMENT: usize = 16;
pub const ROC_ERASED_CALLABLE_PAYLOAD_ALIGNMENT: usize = 16;
pub const ROC_ERASED_CALLABLE_CAPTURE_OFFSET: usize =
    (core::mem::size_of::<RocErasedCallablePayload>() + 15) & !15;

#[inline]
pub fn roc_erased_callable_payload_size(capture_size: usize) -> usize {
    checked_add_usize(
        ROC_ERASED_CALLABLE_CAPTURE_OFFSET,
        capture_size,
        "Roc erased-callable payload size overflow",
    )
}

#[inline]
/// # Safety
/// `callable` must be a non-null Roc erased-callable data pointer.
pub unsafe fn roc_erased_callable_payload_ptr(callable: *mut u8) -> *mut RocErasedCallablePayload {
    callable as *mut RocErasedCallablePayload
}

#[inline]
/// # Safety
/// `callable` must be a non-null Roc erased-callable data pointer.
pub unsafe fn roc_erased_callable_capture_ptr(callable: *mut u8) -> *mut u8 {
    callable.add(ROC_ERASED_CALLABLE_CAPTURE_OFFSET)
}

/// Allocate a Roc erased callable payload.
///
/// # Safety
/// The caller must initialize and use the returned callable according to Roc's
/// erased-callable ABI. `callable_fn_ptr` and `on_drop` must have matching ABI
/// signatures for the captured payload.
pub unsafe fn roc_erased_callable_allocate(
    callable_fn_ptr: RocErasedCallableFn,
    on_drop: Option<RocErasedCallableOnDrop>,
    capture_size: usize,
) -> RocErasedCallable {
    let ptr_width = core::mem::size_of::<usize>();
    let alignment = core::cmp::max(ptr_width, ROC_ERASED_CALLABLE_PAYLOAD_ALIGNMENT);
    let extra_bytes = core::cmp::max(ptr_width, ROC_ERASED_CALLABLE_PAYLOAD_ALIGNMENT);
    let total = checked_add_usize(
        extra_bytes,
        roc_erased_callable_payload_size(capture_size),
        "Roc erased-callable allocation size overflow",
    );
    let base = roc_alloc_bytes(alignment, total) as *mut u8;
    let data = base.add(extra_bytes);
    let rc = data.sub(core::mem::size_of::<isize>()) as *mut isize;
    *rc = 1;
    let payload = roc_erased_callable_payload_ptr(data);
    *payload = RocErasedCallablePayload { callable_fn_ptr, on_drop, on_copy: None, capture_size };
    RocErasedCallable::from_raw(data)
}

// Ownership
//
// Every Roc value a host holds is one owned reference. A type whose values the
// host can release implements `Drop`, and `Clone` adds a reference; a type
// holding a value only Roc can release has neither, and is handed back to Roc
// by moving it into a call. Drop glue carries the whole release plan: a record
// drops its fields, a list its elements, a box its payload.
//
// Send and Sync: compiled Roc code updates the count of every allocation a host
// can see atomically (`rcAtomicity` in `src/lir/arc.zig` keeps a count
// single-threaded only when the allocation is proven never to reach the host),
// so a Roc value may move to and be shared with any thread. The host's
// allocator must be thread-safe; see `RocRuntime`.

const ROC_REFCOUNT_STATIC_DATA: isize = 0;

/// Bytes before a data pointer that belong to its allocation: the refcount,
/// plus the element count when the contents hold Roc references, rounded up to
/// the contents' alignment.
#[inline]
const fn roc_header_bytes(contains_refcounted: bool, alignment: usize) -> usize {
    let ptr_width = core::mem::size_of::<usize>();
    let required = if contains_refcounted { 2 * ptr_width } else { ptr_width };
    if required > alignment { required } else { alignment }
}

#[inline]
const fn roc_allocation_alignment(alignment: usize) -> usize {
    let ptr_width = core::mem::align_of::<usize>();
    if alignment > ptr_width { alignment } else { ptr_width }
}

/// The refcount word just before `data`.
///
/// # Safety
/// `data` is the non-null data pointer of a live Roc allocation.
#[inline]
unsafe fn roc_refcount(data: *mut u8) -> *const AtomicIsize {
    unsafe { data.sub(core::mem::size_of::<isize>()) as *const AtomicIsize }
}

/// Add one reference. Null and static data hold no count.
///
/// # Safety
/// `data` is null or the data pointer of a live Roc allocation.
#[inline]
unsafe fn roc_retain(data: *mut u8) {
    if data.is_null() {
        return;
    }
    let rc = unsafe { &*roc_refcount(data) };
    if rc.load(Ordering::Relaxed) == ROC_REFCOUNT_STATIC_DATA {
        return;
    }
    rc.fetch_add(1, Ordering::Relaxed);
}

/// Release one reference, returning true when it was the last one. The
/// caller then tears down the contents and frees the allocation; the
/// decrement claims the last reference before any content is read, so
/// concurrent releases neither skip nor repeat the teardown.
///
/// # Safety
/// `data` is null or the data pointer of a live Roc allocation, and the
/// caller owns one reference to it.
#[inline]
unsafe fn roc_release(data: *mut u8) -> bool {
    if data.is_null() {
        return false;
    }
    let rc = unsafe { &*roc_refcount(data) };
    if rc.load(Ordering::Relaxed) == ROC_REFCOUNT_STATIC_DATA {
        return false;
    }
    if rc.fetch_sub(1, Ordering::Release) != 1 {
        return false;
    }
    fence(Ordering::Acquire);
    true
}

/// True when `data` is a counted allocation with exactly one reference.
///
/// # Safety
/// `data` is null or the data pointer of a live Roc allocation.
#[inline]
unsafe fn roc_has_one_ref(data: *mut u8) -> bool {
    if data.is_null() {
        return false;
    }
    unsafe { (*roc_refcount(data)).load(Ordering::Acquire) == 1 }
}

/// The count of a counted allocation, or `None` for no allocation, static
/// data (count 0) or a frame callable (negative count).
///
/// # Safety
/// `data` is null or the data pointer of a live Roc allocation.
#[inline]
unsafe fn roc_refcount_value(data: *mut u8) -> Option<usize> {
    if data.is_null() {
        return None;
    }
    let count = unsafe { (*roc_refcount(data)).load(Ordering::Acquire) };
    if count > 0 {
        Some(count as usize)
    } else {
        None
    }
}

/// Free an allocation whose last reference was just released.
///
/// # Safety
/// `data` is the data pointer of an allocation with this header and
/// alignment, and nothing uses it after this call.
#[inline]
unsafe fn roc_free(data: *mut u8, header_bytes: usize, alignment: usize) {
    unsafe { roc_dealloc_bytes(data.sub(header_bytes) as *mut c_void, roc_allocation_alignment(alignment)) }
}

/// Allocate `data_bytes` behind a header, with one reference.
///
/// # Safety
/// The caller initializes the data before Roc or a safe API reads it.
#[inline]
unsafe fn roc_allocate(data_bytes: usize, contains_refcounted: bool, alignment: usize) -> *mut u8 {
    let header_bytes = roc_header_bytes(contains_refcounted, alignment);
    let total = checked_add_usize(header_bytes, data_bytes, "Roc allocation size overflow");
    unsafe {
        let base = roc_alloc_bytes(roc_allocation_alignment(alignment), total) as *mut u8;
        let data = base.add(header_bytes);
        (data.sub(core::mem::size_of::<isize>()) as *mut isize).write(1);
        data
    }
}

/// A type that can be a `RocList` element or a `RocBox` payload.
///
/// `REFCOUNTED` says whether a value of the type holds a Roc reference. It
/// decides the allocation header of the list or box that holds the value, so a
/// wrong value corrupts the heap. Glue emits every implementation from the
/// compiler's ownership plan for the type; a value that holds a reference only
/// Roc can release has no implementation, and its lists and boxes are
/// `RocHeldList` and `RocHeldBox`.
///
/// # Safety
/// `REFCOUNTED` matches the compiler's layout for the type.
pub unsafe trait RocElement {
    const REFCOUNTED: bool;
}

macro_rules! roc_plain_elements {
    ($($plain:ty),* $(,)?) => {
        $(unsafe impl RocElement for $plain {
            const REFCOUNTED: bool = false;
        })*
    };
}

roc_plain_elements!(
    (), bool, u8, i8, u16, i16, u32, i32, u64, i64, u128, i128, f32, f64, RocDec,
    RocU8x16, RocI8x16, RocU16x8, RocI16x8, RocU32x4, RocI32x4, RocU64x2, RocI64x2,
);

unsafe impl RocElement for RocStr {
    const REFCOUNTED: bool = true;
}

unsafe impl<T: RocElement> RocElement for RocList<T> {
    const REFCOUNTED: bool = true;
}

unsafe impl<T: RocElement> RocElement for RocBox<T> {
    const REFCOUNTED: bool = true;
}

unsafe impl RocElement for RocErasedCallable {
    const REFCOUNTED: bool = true;
}

/// One owned reference to a Roc `Box(T)`.
///
/// Boxes are shared, like `Arc`: `clone` adds a reference, `drop` releases
/// one, and the last release drops the payload and frees the box. Read the
/// payload through `Deref`. A box of a zero-sized payload is null, as in Roc.
#[repr(transparent)]
pub struct RocBox<T: RocElement> {
    data: *mut T,
}

// See "Send and Sync" above.
unsafe impl<T: RocElement + Send + Sync> Send for RocBox<T> {}
// See "Send and Sync" above.
unsafe impl<T: RocElement + Send + Sync> Sync for RocBox<T> {}

impl<T: RocElement> RocBox<T> {
    const HEADER_BYTES: usize = roc_header_bytes(T::REFCOUNTED, core::mem::align_of::<T>());

    /// Allocate a box holding `value`.
    pub fn new(value: T) -> Self {
        if core::mem::size_of::<T>() == 0 {
            core::mem::forget(value);
            return Self { data: core::ptr::null_mut() };
        }
        unsafe {
            let data = roc_allocate(core::mem::size_of::<T>(), T::REFCOUNTED, core::mem::align_of::<T>()) as *mut T;
            data.write(value);
            Self { data }
        }
    }

    /// Take ownership of one reference to a box.
    ///
    /// # Safety
    /// `data` is a Roc box data pointer of this payload type, and the caller
    /// gives up the reference it owned.
    pub unsafe fn from_raw(data: *mut T) -> Self {
        Self { data }
    }

    /// Give up ownership of the reference without releasing it.
    pub fn into_raw(self) -> *mut T {
        let data = self.data;
        core::mem::forget(self);
        data
    }

    pub fn as_ptr(&self) -> *const T {
        self.data
    }

    /// True when this is the only reference to the box.
    pub fn is_unique(&self) -> bool {
        self.data.is_null() || unsafe { roc_has_one_ref(self.data as *mut u8) }
    }

    /// The box's reference count, or `None` for a zero-sized payload or
    /// static data, which are not counted.
    pub fn refcount(&self) -> Option<usize> {
        unsafe { roc_refcount_value(self.data as *mut u8) }
    }
}

impl<T: RocElement> core::ops::Deref for RocBox<T> {
    type Target = T;

    fn deref(&self) -> &T {
        if core::mem::size_of::<T>() == 0 {
            unsafe { &*core::ptr::NonNull::<T>::dangling().as_ptr() }
        } else {
            unsafe { &*self.data }
        }
    }
}

impl<T: RocElement> Clone for RocBox<T> {
    fn clone(&self) -> Self {
        unsafe { roc_retain(self.data as *mut u8) };
        Self { data: self.data }
    }
}

impl<T: RocElement> Drop for RocBox<T> {
    fn drop(&mut self) {
        unsafe {
            if roc_release(self.data as *mut u8) {
                core::ptr::drop_in_place(self.data);
                roc_free(self.data as *mut u8, Self::HEADER_BYTES, core::mem::align_of::<T>());
            }
        }
    }
}

impl<T: RocElement + core::fmt::Debug> core::fmt::Debug for RocBox<T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_tuple("RocBox").field(&**self).finish()
    }
}

/// One reference to a Roc `Box(T)` whose payload holds a value only Roc can
/// release.
///
/// The payload's layout is known, so the host can read it, but the host can
/// neither release the box nor allocate one. Move it, `retain` it, and hand it
/// back to Roc by moving it into a call that takes ownership.
#[repr(transparent)]
#[must_use = "only Roc can release this box: hand it back to Roc"]
pub struct RocHeldBox<T> {
    data: *mut T,
}

// See "Send and Sync" above.
unsafe impl<T: Send + Sync> Send for RocHeldBox<T> {}
// See "Send and Sync" above.
unsafe impl<T: Send + Sync> Sync for RocHeldBox<T> {}

impl<T> RocHeldBox<T> {
    /// Add a reference, returning it as a second handle that must also be
    /// handed back to Roc.
    pub fn retain(&self) -> Self {
        unsafe { roc_retain(self.data as *mut u8) };
        Self { data: self.data }
    }

    pub fn as_ptr(&self) -> *const T {
        self.data
    }
}

impl<T> core::ops::Deref for RocHeldBox<T> {
    type Target = T;

    fn deref(&self) -> &T {
        if core::mem::size_of::<T>() == 0 {
            unsafe { &*core::ptr::NonNull::<T>::dangling().as_ptr() }
        } else {
            unsafe { &*self.data }
        }
    }
}

/// One reference to a Roc `Box(T)` whose payload type only the application
/// knows.
///
/// The host can move it, `retain` it, and hand it back to Roc by moving it
/// into a call that takes ownership; only Roc can release it.
#[repr(transparent)]
#[must_use = "only Roc can release this box: hand it back to Roc"]
pub struct RocOpaqueBox {
    data: *mut c_void,
}

// See "Send and Sync" above.
unsafe impl Send for RocOpaqueBox {}
// See "Send and Sync" above.
unsafe impl Sync for RocOpaqueBox {}

impl RocOpaqueBox {
    /// Add a reference, returning it as a second handle that must also be
    /// handed back to Roc.
    pub fn retain(&self) -> Self {
        unsafe { roc_retain(self.data as *mut u8) };
        Self { data: self.data }
    }

    pub fn as_ptr(&self) -> *const c_void {
        self.data
    }
}

/// One owned reference to a Roc `Box(fn)`: an erased callable.
#[repr(transparent)]
pub struct RocErasedCallable {
    data: *mut u8,
}

// See "Send and Sync" above. A borrowed call transfers no ownership, so
// concurrent calls cannot reuse or mutate the capture.
unsafe impl Send for RocErasedCallable {}
// See "Send and Sync" above.
unsafe impl Sync for RocErasedCallable {}

impl RocErasedCallable {
    const HEADER_BYTES: usize = roc_header_bytes(false, ROC_ERASED_CALLABLE_PAYLOAD_ALIGNMENT);

    /// Take ownership of one reference to a callable.
    ///
    /// # Safety
    /// `data` is a Roc erased-callable data pointer, and the caller gives up
    /// the reference it owned.
    pub unsafe fn from_raw(data: *mut u8) -> Self {
        Self { data }
    }

    /// Give up ownership of the reference without releasing it.
    pub fn into_raw(self) -> *mut u8 {
        let data = self.data;
        core::mem::forget(self);
        data
    }

    pub fn as_ptr(&self) -> *mut u8 {
        self.data
    }

    /// The callable's reference count, or `None` for static data.
    pub fn refcount(&self) -> Option<usize> {
        unsafe { roc_refcount_value(self.data) }
    }
}

impl Clone for RocErasedCallable {
    fn clone(&self) -> Self {
        unsafe { roc_retain(self.data) };
        Self { data: self.data }
    }
}

impl Drop for RocErasedCallable {
    fn drop(&mut self) {
        unsafe {
            if roc_release(self.data) {
                let payload = roc_erased_callable_payload_ptr(self.data);
                if let Some(on_drop) = (*payload).on_drop {
                    on_drop(roc_erased_callable_capture_ptr(self.data), raw::RocSymbolAdapter::ptr());
                }
                roc_free(self.data, Self::HEADER_BYTES, ROC_ERASED_CALLABLE_PAYLOAD_ALIGNMENT);
            }
        }
    }
}

impl core::fmt::Debug for RocErasedCallable {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_tuple("RocErasedCallable").field(&self.data).finish()
    }
}

/// One owned reference to a Roc string. Small strings (up to 23 bytes on
/// 64-bit) are stored inline; larger strings are heap-allocated and counted.
///
/// `clone` adds a reference and `drop` releases one, freeing the bytes with
/// the last.
///
/// `bytes` is never tagged. Operations, host code, glue code, and object-file
/// relocations can use it directly as the UTF-8 byte pointer for non-small
/// strings. Seamless-slice tagging lives in `capacity_or_alloc_ptr` instead.
/// Big-string capacity is stored shifted left by one bit, so max capacity is
/// essentially `isize::MAX` bytes: about 2 GiB on 32-bit targets and 8 EiB on
/// 64-bit targets.
///
/// This type is ABI-compatible with the Zig RocStr (24 bytes, `#[repr(C)]`).
#[repr(C)]
pub struct RocStr {
    bytes: *mut u8,
    capacity_or_alloc_ptr: usize,
    length: usize,
}

// See "Send and Sync" above.
unsafe impl Send for RocStr {}
// See "Send and Sync" above.
unsafe impl Sync for RocStr {}

const _: () = assert!(core::mem::size_of::<RocStr>() == 3 * core::mem::size_of::<usize>(), "RocStr size mismatch");
const _: () = assert!(core::mem::align_of::<RocStr>() == core::mem::align_of::<usize>(), "RocStr alignment mismatch");
const _: () = assert!(core::mem::offset_of!(RocStr, bytes) == 0, "RocStr.bytes offset mismatch");
const _: () = assert!(core::mem::offset_of!(RocStr, capacity_or_alloc_ptr) == core::mem::size_of::<usize>(), "RocStr.capacity_or_alloc_ptr offset mismatch");
const _: () = assert!(core::mem::offset_of!(RocStr, length) == 2 * core::mem::size_of::<usize>(), "RocStr.length offset mismatch");

const ROC_STR_SIZE: usize = core::mem::size_of::<RocStr>();
const ROC_SMALL_STR_MAX_LEN: usize = ROC_STR_SIZE - 1;
const ROC_SMALL_STR_BIT: usize = isize::MIN as usize;
const ROC_SEAMLESS_SLICE_TAG: usize = 1;

impl RocStr {
    /// Return an empty RocStr (small string with zero length).
    pub fn empty() -> Self {
        Self {
            bytes: core::ptr::null_mut(),
            capacity_or_alloc_ptr: 0,
            length: ROC_SMALL_STR_BIT,
        }
    }

    /// Return true if this string is stored inline (small string optimization).
    #[inline]
    pub fn is_small_str(&self) -> bool {
        (self.length as isize) < 0
    }

    /// Return true if this string is a seamless slice into another allocation.
    #[inline]
    pub fn is_seamless_slice(&self) -> bool {
        !self.is_small_str() && (self.capacity_or_alloc_ptr & ROC_SEAMLESS_SLICE_TAG) != 0
    }

    /// Return the length of the string in bytes.
    #[inline]
    pub fn len(&self) -> usize {
        if self.is_small_str() {
            let bytes_ptr = self as *const Self as *const u8;
            let last_byte = unsafe { *bytes_ptr.add(ROC_STR_SIZE - 1) };
            (last_byte ^ 0b1000_0000) as usize
        } else {
            self.length
        }
    }

    /// Return true if the string has zero length.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Return the string contents as a byte slice.
    pub fn as_slice(&self) -> &[u8] {
        let ptr = self.as_u8_ptr();
        if ptr.is_null() {
            return &[];
        }
        unsafe { core::slice::from_raw_parts(ptr, self.len()) }
    }

    /// Return a pointer to the raw UTF-8 bytes.
    #[inline]
    pub fn as_u8_ptr(&self) -> *const u8 {
        if self.is_small_str() {
            self as *const Self as *const u8
        } else {
            self.bytes as *const u8
        }
    }

    /// Return the string contents as a `&str`.
    pub fn as_str(&self) -> &str {
        // Every RocStr holds UTF-8: Roc never produces anything else, and the
        // host constructors take a `&str`, validate (`try_from_utf8`), or
        // require it (`from_raw_parts`).
        unsafe { core::str::from_utf8_unchecked(self.as_slice()) }
    }

    /// Create a RocStr from UTF-8 bytes, or say why they are not UTF-8.
    pub fn try_from_utf8(bytes: &[u8]) -> Result<Self, core::str::Utf8Error> {
        Ok(Self::from_str(core::str::from_utf8(bytes)?))
    }

    /// Take ownership of one reference to a big string from its three raw
    /// fields, exactly as the ABI lays them out.
    ///
    /// The escape hatch for a string the host builds itself, such as a
    /// seamless slice over static data that borrows a host buffer.
    ///
    /// # Safety
    /// `bytes..bytes + length` is valid UTF-8 for as long as the string or any
    /// clone of it lives; `length` has its top bit clear (this is never a
    /// small string); and `capacity_or_alloc_ptr` is either a shifted capacity
    /// with `bytes` a counted allocation, or a seamless-slice tagged pointer
    /// to the allocation whose refcount word precedes it. The caller gives up
    /// the reference it owned.
    pub unsafe fn from_raw_parts(bytes: *mut u8, capacity_or_alloc_ptr: usize, length: usize) -> Self {
        Self { bytes, capacity_or_alloc_ptr, length }
    }

    /// Create a RocStr from a `&str`, allocating through `roc_alloc` if needed.
    pub fn from_str(text: &str) -> Self {
        let slice = text.as_bytes();
        if slice.len() <= ROC_SMALL_STR_MAX_LEN {
            let mut result = Self::empty();
            let ptr = &mut result as *mut Self as *mut u8;
            unsafe {
                core::ptr::copy_nonoverlapping(slice.as_ptr(), ptr, slice.len());
                *ptr.add(ROC_STR_SIZE - 1) = (slice.len() as u8) | 0b1000_0000;
            }
            result
        } else {
            unsafe {
                let data = roc_allocate(slice.len(), false, core::mem::align_of::<usize>());
                core::ptr::copy_nonoverlapping(slice.as_ptr(), data, slice.len());
                Self {
                    bytes: data,
                    capacity_or_alloc_ptr: shifted_capacity(slice.len()),
                    length: slice.len(),
                }
            }
        }
    }

    /// Return true if this string has a reference count of exactly one, or
    /// holds no counted allocation at all.
    pub fn is_unique(&self) -> bool {
        if self.is_small_str() {
            return true;
        }
        let alloc_ptr = self.allocation_ptr();
        if alloc_ptr.is_null() {
            return true;
        }
        unsafe {
            let count = (*roc_refcount(alloc_ptr)).load(Ordering::Acquire);
            count == ROC_REFCOUNT_STATIC_DATA || count == 1
        }
    }

    /// The allocation's reference count, or `None` for a small string or
    /// static data, which are not counted.
    pub fn refcount(&self) -> Option<usize> {
        unsafe { roc_refcount_value(self.allocation_ptr()) }
    }

    /// The data pointer of the counted allocation, or null for a small string.
    fn allocation_ptr(&self) -> *mut u8 {
        if self.is_small_str() {
            core::ptr::null_mut()
        } else if self.is_seamless_slice() {
            (self.capacity_or_alloc_ptr & !ROC_SEAMLESS_SLICE_TAG) as *mut u8
        } else {
            self.bytes
        }
    }
}

impl From<&str> for RocStr {
    fn from(text: &str) -> Self {
        Self::from_str(text)
    }
}

impl Clone for RocStr {
    fn clone(&self) -> Self {
        unsafe { roc_retain(self.allocation_ptr()) };
        Self {
            bytes: self.bytes,
            capacity_or_alloc_ptr: self.capacity_or_alloc_ptr,
            length: self.length,
        }
    }
}

impl Drop for RocStr {
    fn drop(&mut self) {
        let alloc_ptr = self.allocation_ptr();
        unsafe {
            if roc_release(alloc_ptr) {
                roc_free(alloc_ptr, roc_header_bytes(false, core::mem::align_of::<usize>()), core::mem::align_of::<usize>());
            }
        }
    }
}

impl core::fmt::Debug for RocStr {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_struct("RocStr")
            .field("len", &self.len())
            .field("is_small", &self.is_small_str())
            .finish()
    }
}

/// One owned reference to a Roc list.
///
/// The allocation header follows from the element type (`T::REFCOUNTED`), so a
/// list cannot be given the wrong one. `clone` adds a reference to the
/// allocation without touching the elements; `drop` releases one, and the last
/// release drops every element of the allocation and frees it. Lists whose
/// header the host must choose itself are `RocListRaw`.
#[repr(C)]
pub struct RocList<T: RocElement> {
    elements: *mut T,
    length: usize,
    capacity_or_alloc_ptr: usize,
}

// See "Send and Sync" above.
unsafe impl<T: RocElement + Send + Sync> Send for RocList<T> {}
// See "Send and Sync" above.
unsafe impl<T: RocElement + Send + Sync> Sync for RocList<T> {}

const _: () = assert!(core::mem::size_of::<RocList<u8>>() == 3 * core::mem::size_of::<usize>(), "RocList size mismatch");
const _: () = assert!(core::mem::align_of::<RocList<u8>>() == core::mem::align_of::<usize>(), "RocList alignment mismatch");
const _: () = assert!(core::mem::offset_of!(RocList<u8>, elements) == 0, "RocList.elements offset mismatch");
const _: () = assert!(core::mem::offset_of!(RocList<u8>, length) == core::mem::size_of::<usize>(), "RocList.length offset mismatch");
const _: () = assert!(core::mem::offset_of!(RocList<u8>, capacity_or_alloc_ptr) == 2 * core::mem::size_of::<usize>(), "RocList.capacity_or_alloc_ptr offset mismatch");

const ROC_LIST_SEAMLESS_SLICE_TAG: usize = 1;

/// The data pointer of a list's counted allocation, or null when it has none.
/// A seamless slice names its allocation in `capacity_or_alloc_ptr`.
#[inline]
fn roc_list_allocation_ptr(elements: *mut u8, capacity_or_alloc_ptr: usize) -> *mut u8 {
    if capacity_or_alloc_ptr == 0 {
        core::ptr::null_mut()
    } else if (capacity_or_alloc_ptr & ROC_LIST_SEAMLESS_SLICE_TAG) != 0 {
        (capacity_or_alloc_ptr & !ROC_LIST_SEAMLESS_SLICE_TAG) as *mut u8
    } else {
        elements
    }
}

impl<T: RocElement> RocList<T> {
    const HEADER_BYTES: usize = roc_header_bytes(T::REFCOUNTED, core::mem::align_of::<T>());

    /// Return an empty RocList.
    pub fn empty() -> Self {
        Self {
            elements: core::ptr::null_mut(),
            length: 0,
            capacity_or_alloc_ptr: 0,
        }
    }

    /// Return the number of elements in the list.
    #[inline]
    pub fn len(&self) -> usize {
        self.length
    }

    /// Return true if the list has zero elements.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }

    /// Return true if this list is a seamless slice into another allocation.
    #[inline]
    pub fn is_seamless_slice(&self) -> bool {
        (self.capacity_or_alloc_ptr & ROC_LIST_SEAMLESS_SLICE_TAG) != 0
    }

    fn allocation_ptr(&self) -> *mut T {
        roc_list_allocation_ptr(self.elements as *mut u8, self.capacity_or_alloc_ptr) as *mut T
    }

    /// The number of elements the allocation holds, which a seamless slice of
    /// refcounted elements records in its header.
    fn allocation_element_count(&self) -> usize {
        if self.is_seamless_slice() && T::REFCOUNTED {
            unsafe { *(self.allocation_ptr() as *const usize).sub(2) }
        } else {
            self.length
        }
    }

    /// Return the list elements as a slice.
    pub fn as_slice(&self) -> &[T] {
        if self.elements.is_null() {
            &[]
        } else {
            unsafe { core::slice::from_raw_parts(self.elements, self.length) }
        }
    }

    /// Iterate over borrowed elements.
    pub fn iter(&self) -> core::slice::Iter<'_, T> {
        self.as_slice().iter()
    }

    /// Allocate a new list with space for `length` elements. A length whose
    /// allocation cannot be represented stops the program through
    /// `roc_crashed`; `try_allocate` reports it instead.
    ///
    /// # Safety
    /// The element memory is uninitialized while `length` is already set. The
    /// caller initializes every element before the list is read, dropped, or
    /// handed to Roc.
    pub unsafe fn allocate(length: usize) -> Self {
        if length == 0 {
            return Self::empty();
        }
        unsafe {
            let data = Self::allocate_elements(length);
            if T::REFCOUNTED {
                (data as *mut usize).sub(2).write(length);
            }
            Self {
                elements: data,
                length,
                capacity_or_alloc_ptr: shifted_capacity(length),
            }
        }
    }

    /// `allocate`, returning `Err` when the allocation for `length` elements
    /// cannot be represented.
    ///
    /// # Safety
    /// As for `allocate`.
    pub unsafe fn try_allocate(length: usize) -> Result<Self, RocCapacityOverflow> {
        let fits = length <= isize::MAX as usize
            && length
                .checked_mul(core::mem::size_of::<T>())
                .and_then(|bytes| bytes.checked_add(Self::HEADER_BYTES))
                .is_some_and(|total| total <= isize::MAX as usize);
        if fits {
            Ok(unsafe { Self::allocate(length) })
        } else {
            Err(RocCapacityOverflow)
        }
    }

    /// Allocate room for `capacity` elements behind a header with one
    /// reference, returning the element pointer.
    ///
    /// # Safety
    /// The elements are uninitialized.
    unsafe fn allocate_elements(capacity: usize) -> *mut T {
        let data_bytes = checked_mul_usize(capacity, core::mem::size_of::<T>(), "RocList allocation size overflow");
        unsafe { roc_allocate(data_bytes, T::REFCOUNTED, core::mem::align_of::<T>()) as *mut T }
    }

    /// The distance in bytes between consecutive elements, which glue asserts
    /// equals the compiler's element size.
    pub const fn element_stride() -> usize {
        core::mem::size_of::<T>()
    }

    /// The allocation's reference count, or `None` for an empty list or
    /// static data, which are not counted.
    pub fn refcount(&self) -> Option<usize> {
        unsafe { roc_refcount_value(self.allocation_ptr() as *mut u8) }
    }

    /// Create a RocList holding a clone of each element of `slice`.
    pub fn from_slice(slice: &[T]) -> Self
    where
        T: Clone,
    {
        let list = unsafe { Self::allocate(slice.len()) };
        for (index, item) in slice.iter().enumerate() {
            unsafe { list.elements.add(index).write(item.clone()) };
        }
        list
    }

    /// Return true if this list has a reference count of exactly one, or holds
    /// no counted allocation at all.
    pub fn is_unique(&self) -> bool {
        let alloc_ptr = self.allocation_ptr() as *mut u8;
        if alloc_ptr.is_null() {
            return true;
        }
        unsafe {
            let count = (*roc_refcount(alloc_ptr)).load(Ordering::Acquire);
            count == ROC_REFCOUNT_STATIC_DATA || count == 1
        }
    }

    /// Return true if this list's allocation has exactly one counted reference.
    pub fn has_one_ref(&self) -> bool {
        unsafe { roc_has_one_ref(self.allocation_ptr() as *mut u8) }
    }

    /// Move the elements out, if this is the only reference to the allocation.
    ///
    /// Elements belong to the allocation, not to any one reference, so they can
    /// be moved out only by the last owner. Otherwise the list is handed back
    /// unchanged, as with `Rc::try_unwrap`; there is no clone-on-shared path.
    pub fn try_into_iter(self) -> Result<RocListIntoIter<T>, Self> {
        let allocation = self.allocation_ptr();
        // A list with no counted allocation owns nothing it could move out
        // unless it is empty.
        let is_movable = if allocation.is_null() { self.length == 0 } else { self.has_one_ref() };
        if !is_movable {
            return Err(self);
        }
        let list = core::mem::ManuallyDrop::new(self);
        let slice_start = if list.elements.is_null() {
            0
        } else {
            (list.elements as usize - allocation as usize) / core::mem::size_of::<T>().max(1)
        };
        Ok(RocListIntoIter {
            allocation,
            allocation_count: list.allocation_element_count(),
            slice_start,
            next: slice_start,
            end: slice_start + list.length,
        })
    }
}

/// A list length whose allocation size cannot be represented.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RocCapacityOverflow;

impl<T: RocElement> FromIterator<T> for RocList<T> {
    /// Collect into a new list, growing its allocation as items arrive.
    fn from_iter<I: IntoIterator<Item = T>>(items: I) -> Self {
        let items = items.into_iter();
        let mut capacity = items.size_hint().0;
        let mut data = if capacity == 0 { core::ptr::null_mut() } else { unsafe { Self::allocate_elements(capacity) } };
        let mut length = 0;
        for item in items {
            if length == capacity {
                let grown = if capacity == 0 { 4 } else { checked_mul_usize(capacity, 2, "RocList capacity overflow") };
                unsafe {
                    let next = Self::allocate_elements(grown);
                    if !data.is_null() {
                        core::ptr::copy_nonoverlapping(data, next, length);
                        roc_free(data as *mut u8, Self::HEADER_BYTES, core::mem::align_of::<T>());
                    }
                    data = next;
                }
                capacity = grown;
            }
            unsafe { data.add(length).write(item) };
            length += 1;
        }
        if length == 0 {
            if !data.is_null() {
                unsafe { roc_free(data as *mut u8, Self::HEADER_BYTES, core::mem::align_of::<T>()) };
            }
            return Self::empty();
        }
        if T::REFCOUNTED {
            unsafe { (data as *mut usize).sub(2).write(length) };
        }
        Self {
            elements: data,
            length,
            capacity_or_alloc_ptr: shifted_capacity(capacity),
        }
    }
}

impl<T: RocElement> Clone for RocList<T> {
    fn clone(&self) -> Self {
        unsafe { roc_retain(self.allocation_ptr() as *mut u8) };
        Self {
            elements: self.elements,
            length: self.length,
            capacity_or_alloc_ptr: self.capacity_or_alloc_ptr,
        }
    }
}

impl<T: RocElement> Drop for RocList<T> {
    fn drop(&mut self) {
        let allocation = self.allocation_ptr();
        unsafe {
            if !roc_release(allocation as *mut u8) {
                return;
            }
            if T::REFCOUNTED {
                let count = self.allocation_element_count();
                core::ptr::drop_in_place(core::ptr::slice_from_raw_parts_mut(allocation, count));
            }
            roc_free(allocation as *mut u8, Self::HEADER_BYTES, core::mem::align_of::<T>());
        }
    }
}

impl<T: RocElement + core::fmt::Debug> core::fmt::Debug for RocList<T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_list().entries(self.as_slice().iter()).finish()
    }
}

/// The elements of a uniquely owned `RocList`, moved out one at a time.
///
/// Dropping the iterator drops the elements it has not yielded, every element
/// of the allocation outside the original slice, and the allocation.
pub struct RocListIntoIter<T: RocElement> {
    allocation: *mut T,
    allocation_count: usize,
    slice_start: usize,
    next: usize,
    end: usize,
}

// See "Send and Sync" above.
unsafe impl<T: RocElement + Send + Sync> Send for RocListIntoIter<T> {}
// See "Send and Sync" above.
unsafe impl<T: RocElement + Send + Sync> Sync for RocListIntoIter<T> {}

impl<T: RocElement> Iterator for RocListIntoIter<T> {
    type Item = T;

    fn next(&mut self) -> Option<T> {
        if self.next == self.end {
            return None;
        }
        let item = unsafe { self.allocation.add(self.next).read() };
        self.next += 1;
        Some(item)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.end - self.next;
        (remaining, Some(remaining))
    }
}

impl<T: RocElement> ExactSizeIterator for RocListIntoIter<T> {}

impl<T: RocElement> Drop for RocListIntoIter<T> {
    fn drop(&mut self) {
        if self.allocation.is_null() {
            return;
        }
        unsafe {
            if T::REFCOUNTED {
                let before = core::ptr::slice_from_raw_parts_mut(self.allocation, self.slice_start);
                let unyielded = core::ptr::slice_from_raw_parts_mut(self.allocation.add(self.next), self.end - self.next);
                let after = core::ptr::slice_from_raw_parts_mut(self.allocation.add(self.end), self.allocation_count - self.end);
                core::ptr::drop_in_place(before);
                core::ptr::drop_in_place(unyielded);
                core::ptr::drop_in_place(after);
            }
            roc_free(self.allocation as *mut u8, RocList::<T>::HEADER_BYTES, core::mem::align_of::<T>());
        }
    }
}

/// A Roc list whose allocation header the host chooses: `REFCOUNTED` must be
/// whether the elements hold Roc references, exactly as the compiler lays the
/// list out.
///
/// The escape hatch for checking glue's belief about an element type. It has
/// no ownership of its own: it is `Copy`, never releases anything, and every
/// access is `unsafe`. Convert to and from `RocList` with `from_list` and
/// `into_list`, which check `REFCOUNTED` against the element type at compile
/// time.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct RocListRaw<T, const REFCOUNTED: bool> {
    pub elements: *mut T,
    pub length: usize,
    pub capacity_or_alloc_ptr: usize,
}

// See "Send and Sync" above.
unsafe impl<T: Send + Sync, const REFCOUNTED: bool> Send for RocListRaw<T, REFCOUNTED> {}
// See "Send and Sync" above.
unsafe impl<T: Send + Sync, const REFCOUNTED: bool> Sync for RocListRaw<T, REFCOUNTED> {}

impl<T, const REFCOUNTED: bool> RocListRaw<T, REFCOUNTED> {
    /// Take the raw parts of an owned list, which this value now carries.
    pub fn from_list(list: RocList<T>) -> Self
    where
        T: RocElement,
    {
        const { assert!(T::REFCOUNTED == REFCOUNTED, "RocListRaw header disagrees with the element type") };
        let list = core::mem::ManuallyDrop::new(list);
        Self { elements: list.elements, length: list.length, capacity_or_alloc_ptr: list.capacity_or_alloc_ptr }
    }

    /// Hand the raw parts back to an owning list.
    ///
    /// # Safety
    /// The parts are one owned reference to a list of `T`.
    pub unsafe fn into_list(self) -> RocList<T>
    where
        T: RocElement,
    {
        const { assert!(T::REFCOUNTED == REFCOUNTED, "RocListRaw header disagrees with the element type") };
        RocList { elements: self.elements, length: self.length, capacity_or_alloc_ptr: self.capacity_or_alloc_ptr }
    }

    /// Return the list elements as a slice.
    ///
    /// # Safety
    /// The parts describe a live list of `length` initialized `T`.
    pub unsafe fn as_slice(&self) -> &[T] {
        if self.elements.is_null() {
            &[]
        } else {
            unsafe { core::slice::from_raw_parts(self.elements, self.length) }
        }
    }

    /// The header size, in bytes, that `REFCOUNTED` implies for this element type.
    pub const fn header_bytes() -> usize {
        roc_header_bytes(REFCOUNTED, core::mem::align_of::<T>())
    }
}

/// A Roc list whose items have a type only the application knows.
///
/// This host knows neither the size of an item nor whether items are
/// refcounted, so it cannot read an item, allocate such a list, or release
/// one. It can move the list, `retain` it, and hand it back to Roc by moving
/// it into a call that takes ownership.
#[repr(C)]
#[must_use = "only Roc can release this list: hand it back to Roc"]
pub struct RocOpaqueList {
    elements: *mut c_void,
    length: usize,
    capacity_or_alloc_ptr: usize,
}

// See "Send and Sync" above.
unsafe impl Send for RocOpaqueList {}
// See "Send and Sync" above.
unsafe impl Sync for RocOpaqueList {}

impl RocOpaqueList {
    /// Return the number of items in the list.
    #[inline]
    pub fn len(&self) -> usize {
        self.length
    }

    /// Return true if the list has zero items.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }

    /// Add a reference, returning it as a second handle that must also be
    /// handed back to Roc.
    pub fn retain(&self) -> Self {
        unsafe { roc_retain(roc_list_allocation_ptr(self.elements as *mut u8, self.capacity_or_alloc_ptr)) };
        Self { elements: self.elements, length: self.length, capacity_or_alloc_ptr: self.capacity_or_alloc_ptr }
    }
}

/// A Roc list whose items hold opaque Roc values.
///
/// The items have a known layout, so the host can read them. Whether the
/// opaque values inside them are refcounted is known only to Roc, and the
/// list's allocation header depends on it, so the host cannot allocate such a
/// list or release one. It can move the list, `retain` it, and hand it back to
/// Roc by moving it into a call that takes ownership.
#[repr(C)]
#[must_use = "only Roc can release this list: hand it back to Roc"]
pub struct RocHeldList<T> {
    elements: *mut T,
    length: usize,
    capacity_or_alloc_ptr: usize,
}

// See "Send and Sync" above.
unsafe impl<T: Send + Sync> Send for RocHeldList<T> {}
// See "Send and Sync" above.
