// Entrypoints

/// Call the `app_for_host` entrypoint.
pub fn roc_app() -> AppForHost {
    roc_app_with(&NoContext)
}

/// Call the `app_for_host` entrypoint with `ctx` entered for the call.
pub fn roc_app_with(ctx: &impl RocContext) -> AppForHost {
    let _context = ctx.enter();
    unsafe { raw::roc_app() }
}

/// Call the `init_for_host!` entrypoint.
pub fn roc_init() -> InitForHostResult {
    roc_init_with(&NoContext)
}

/// Call the `init_for_host!` entrypoint with `ctx` entered for the call.
pub fn roc_init_with(ctx: &impl RocContext) -> InitForHostResult {
    let _context = ctx.enter();
    unsafe { raw::roc_init() }
}

